SELECT QUARTER(end_date) end_quarter, status, CASE WHEN monthly_fee >= 260 THEN 'high' WHEN monthly_fee >= 55 THEN 'mid' ELSE 'low' END monthly_fee_bucket, SUM(CASE WHEN plan = 'standard' THEN monthly_fee ELSE 0 END) standard_monthly_fee, SUM(CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END) enterprise_count FROM subscriptions WHERE monthly_fee > 160 AND customer_id IN (17, 27, 29, 39) AND plan <> 'premium' GROUP BY end_quarter, status, monthly_fee_bucket HAVING standard_monthly_fee < 77;
